export async function runAdminApiTests(): Promise<void> {
  {
    const inserts: unknown[][] = [];
    const env = {
      DB: {
        prepare() {
          return {
            bind(...values: unknown[]) {
              inserts.push(values);
              return {
                async run() {
                  return { success: true, meta: { changes: 1 } };
                },
              };
            },
          };
        },
      },
    } as never;

    const response = await handleCreateAdminApiKey(
      new Request('https://example.com/api/admin/keys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ label: 'CI key' }),
      }),
      env,
      createAuthContext({ isHostedMode: true, isAdmin: true })
    );

    assert.equal(response.status, 201);
    const payload = (await response.json()) as {
      key: string;
      accountId: string;
      label: string;
      isAdmin: boolean;
    };
    assert.match(payload.key, /^nmb_live_[a-f0-9]{32}$/);
    assert.match(payload.accountId, /^[0-9a-f-]{36}$/);
    assert.equal(payload.label, 'CI key');
    assert.equal(payload.isAdmin, false);
    assert.equal(inserts.length, 1);
    assert.equal(inserts[0][2], 'CI key');
    assert.equal(inserts[0][3], 0);
  }

  {
    const env = { DB: { prepare() { throw new Error('should not write'); } } } as never;
    const response = await handleCreateAdminApiKey(
      new Request('https://example.com/api/admin/keys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ label: 'Denied key' }),
      }),
      env,
      createAuthContext({ isHostedMode: true, isAdmin: false })
    );
    assert.equal(response.status, 403);
  }

  {
    const env = { DB: { prepare() { throw new Error('should not write'); } } } as never;
    const response = await handleCreateAdminApiKey(
      new Request('https://example.com/api/admin/keys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ label: 'Self hosted key' }),
      }),
      env,
      createAuthContext({ isHostedMode: false, isAdmin: true })
    );
    assert.equal(response.status, 404);
  }

  {
    const env = { DB: { prepare() { throw new Error('should not write'); } } } as never;
    const response = await handleCreateAdminApiKey(
      new Request('https://example.com/api/admin/keys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ label: '   ' }),
      }),
      env,
      createAuthContext({ isHostedMode: true, isAdmin: true })
    );
    assert.equal(response.status, 400);
    const payload = (await response.json()) as { error: string; code: string };
    assert.equal(payload.code, 'invalid_label');
  }
}

import type { AuthContext, Env } from '../types.js';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Idempotency-Key, X-Review-Github-Token, X-Openrouter-Api-Key, X-Nimbus-Api-Key',
};

interface CreateAdminKeyRequest {
  label: string;
  accountId?: string;
  isAdmin?: boolean;
}

interface CreateAdminKeyResponse {
  key: string;
  accountId: string;
  label: string;
  isAdmin: boolean;
}

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'Content-Type': 'application/json',
      ...corsHeaders,
    },
  });
}

function randomHex(bytes: number): string {
  const values = new Uint8Array(bytes);
  crypto.getRandomValues(values);
  return Array.from(values)
    .map((value) => value.toString(16).padStart(2, '0'))
    .join('');
}

async function sha256Hex(input: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(input));
  return Array.from(new Uint8Array(digest))
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join('');
}

export async function handleCreateAdminApiKey(request: Request, env: Env, authContext: AuthContext): Promise<Response> {
  if (authContext.isHostedMode !== true) {
    return jsonResponse({ error: 'Not Found' }, 404);
  }
  if (authContext.isAdmin !== true) {
    return jsonResponse({ error: 'Forbidden', code: 'forbidden' }, 403);
  }

  let payload: CreateAdminKeyRequest;
  try {
    payload = (await request.json()) as CreateAdminKeyRequest;
  } catch {
    return jsonResponse({ error: 'Invalid JSON body', code: 'invalid_json' }, 400);
  }

  const label = typeof payload.label === 'string' ? payload.label.trim() : '';
  if (!label) {
    return jsonResponse({ error: 'label is required', code: 'invalid_label' }, 400);
  }

  if (payload.isAdmin !== undefined && typeof payload.isAdmin !== 'boolean') {
    return jsonResponse({ error: 'isAdmin must be a boolean when provided', code: 'invalid_is_admin' }, 400);
  }

  const accountId = typeof payload.accountId === 'string' && payload.accountId.trim() ? payload.accountId.trim() : crypto.randomUUID();
  const isAdmin = payload.isAdmin === true;
  const key = `nmb_live_${randomHex(16)}`;
  const keyHash = await sha256Hex(key);
  const now = new Date().toISOString();

  await env.DB.prepare(
    'INSERT INTO nimbus_api_keys (key_hash, account_id, label, is_admin, created_at) VALUES (?, ?, ?, ?, ?)'
  )
    .bind(keyHash, accountId, label, isAdmin ? 1 : 0, now)
    .run();

  const response: CreateAdminKeyResponse = {
    key,
    accountId,
    label,
    isAdmin,
  };

  return jsonResponse(response, 201);
}

