Here’s a draft workflow file you can drop in as-is for dogfooding.

```yaml
name: Nimbus PR Review

on:
  pull_request:
    types: [opened, synchronize]

permissions:
  contents: read
  pull-requests: write
  issues: write

jobs:
  nimbus-review:
    name: Nimbus Review (informational)
    runs-on: ubuntu-latest
    timeout-minutes: 10

    env:
      # Required
      NIMBUS_API_KEY: ${{ secrets.NIMBUS_API_KEY }}
      REVIEW_CONTEXT_GITHUB_TOKEN: ${{ secrets.REVIEW_CONTEXT_GITHUB_TOKEN }}
      # Optional override (platform key can be used server-side if omitted)
      OPENROUTER_API_KEY: ${{ secrets.OPENROUTER_API_KEY }}
      # Optional override if you ever need non-default worker URL
      NIMBUS_WORKER_URL: ${{ secrets.NIMBUS_WORKER_URL }}

    steps:
      - name: Validate required secrets
        run: |
          if [ -z "${NIMBUS_API_KEY}" ]; then
            echo "Missing required secret: NIMBUS_API_KEY"
            exit 1
          fi
          if [ -z "${REVIEW_CONTEXT_GITHUB_TOKEN}" ]; then
            echo "Missing required secret: REVIEW_CONTEXT_GITHUB_TOKEN"
            exit 1
          fi

      - name: Checkout
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Fetch Entire checkpoint branch
        run: |
          # Required for local Entire context/co-change resolution in CI.
          git fetch --no-tags origin entire/checkpoints/v1:refs/remotes/origin/entire/checkpoints/v1

      - name: Setup pnpm
        uses: pnpm/action-setup@v4
        with:
          version: 9

      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: pnpm

      - name: Install dependencies
        run: pnpm install --frozen-lockfile

      - name: Run Nimbus review create (non-blocking)
        id: create_review
        continue-on-error: true
        run: |
          HEAD_SHA="${{ github.event.pull_request.head.sha }}"
          BASE_REF="origin/${{ github.event.pull_request.base.ref }}"

          echo "Running Nimbus review for head=${HEAD_SHA} base=${BASE_REF}"
          pnpm --filter @dayhaysoos/nimbus dev review create --commit "${HEAD_SHA}" --base "${BASE_REF}" | tee nimbus-review-create.log

      - name: Parse review id from output
        id: parse_review_id
        if: always()
        run: |
          REVIEW_ID=$(node -e "
            const fs = require('fs');
            const text = fs.existsSync('nimbus-review-create.log') ? fs.readFileSync('nimbus-review-create.log', 'utf8') : '';
            const m = text.match(/Review queued:\\s+(rev_[a-z0-9_]+)/i);
            process.stdout.write(m ? m[1] : '');
          ")
          echo "review_id=${REVIEW_ID}" >> "$GITHUB_OUTPUT"
          echo "Parsed review_id='${REVIEW_ID}'"

      - name: Export review markdown (non-blocking)
        id: export_markdown
        if: always() && steps.parse_review_id.outputs.review_id != ''
        continue-on-error: true
        run: |
          pnpm --filter @dayhaysoos/nimbus dev review export "${{ steps.parse_review_id.outputs.review_id }}" --format markdown --out nimbus-review.md

      - name: Upsert sticky PR comment
        if: always()
        uses: actions/github-script@v7
        env:
          REVIEW_ID: ${{ steps.parse_review_id.outputs.review_id }}
          CREATE_OUTCOME: ${{ steps.create_review.outcome }}
          EXPORT_OUTCOME: ${{ steps.export_markdown.outcome }}
        with:
          script: |
            const fs = require('fs');

            const marker = '<!-- nimbus-review-comment -->';
            const reviewId = process.env.REVIEW_ID || '';
            const createOutcome = process.env.CREATE_OUTCOME || 'unknown';
            const exportOutcome = process.env.EXPORT_OUTCOME || 'skipped';

            const pr = context.payload.pull_request;
            const headSha = pr.head.sha;
            const baseRef = pr.base.ref;
            const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

            let body = `${marker}
            ## Nimbus Review

            - Commit: \`${headSha}\`
            - Base: \`${baseRef}\`
            - Create step: \`${createOutcome}\`
            - Export step: \`${exportOutcome}\`
            - Workflow run: ${runUrl}
            `;

            if (reviewId && fs.existsSync('nimbus-review.md')) {
              const markdown = fs.readFileSync('nimbus-review.md', 'utf8').trim();
              body += `

            ---
            ${markdown}
            `;
            } else {
              body += `

            ---
            Nimbus review did not produce an exportable markdown report in this run.
            Check workflow logs for details.
            `;
            }

            // GitHub comment body max is 65536 chars; keep headroom.
            const max = 65000;
            if (body.length > max) {
              body = body.slice(0, max) + '\n\n... (truncated)';
            }

            const { owner, repo } = context.repo;
            const issue_number = pr.number;

            const comments = await github.paginate(github.rest.issues.listComments, {
              owner,
              repo,
              issue_number,
              per_page: 100,
            });

            const existing = comments.find(c =>
              c.user?.type === 'Bot' &&
              typeof c.body === 'string' &&
              c.body.includes(marker)
            );

            if (existing) {
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: existing.id,
                body,
              });
              core.info(`Updated existing Nimbus comment: ${existing.id}`);
            } else {
              const created = await github.rest.issues.createComment({
                owner,
                repo,
                issue_number,
                body,
              });
              core.info(`Created Nimbus comment: ${created.data.id}`);
            }

      - name: Finalize as informational check
        if: always()
        run: |
          echo "Nimbus PR review completed (informational mode)."
          exit 0
```

Sticky comment update strategy
- Add a unique hidden marker in the comment body: `<!-- nimbus-review-comment -->`.
- On each PR run, list existing PR comments and find the first bot-authored comment containing that marker.
- If found, update that comment in place.
- If not found, create one new comment.
- This guarantees one comment per PR, continuously updated on each `synchronize`, with no duplicates.

